// D1 (SQLite) schema. Plan 003, section 6.
//
// Conventions:
// - Ids are UUID strings generated by the app, as in the browser data today.
// - Times the app shows or sends back are ISO 8601 strings, like the domain schemas.
// - next_reminder_at is a Unix time in milliseconds, because the scheduler compares
//   and indexes it on every run.
import { sql } from 'drizzle-orm'
import { index, integer, primaryKey, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'

const createdAt = () =>
  text('created_at')
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`)

export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    // IANA time zone, e.g. "Africa/Nairobi". Reminder times are computed in it.
    timeZone: text('time_zone').notNull().default('UTC'),
    createdAt: createdAt(),
  },
  (table) => [uniqueIndex('users_email_unique').on(table.email)],
)

// One-time sign-in codes. Only a hash of the code is stored.
export const loginCodes = sqliteTable(
  'login_codes',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    email: text('email').notNull(),
    codeHash: text('code_hash').notNull(),
    expiresAt: text('expires_at').notNull(),
    attempts: integer('attempts').notNull().default(0),
    createdAt: createdAt(),
  },
  (table) => [index('login_codes_email_idx').on(table.email)],
)

// Sessions are looked up by a hash of the cookie value, so a database leak does
// not leak usable sessions.
export const sessions = sqliteTable(
  'sessions',
  {
    idHash: text('id_hash').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    expiresAt: text('expires_at').notNull(),
    createdAt: createdAt(),
  },
  (table) => [index('sessions_user_idx').on(table.userId)],
)

export const routines = sqliteTable(
  'routines',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    // ISO weekdays as a JSON array, e.g. [1,2,3,4,5].
    days: text('days', { mode: 'json' }).$type<number[]>().notNull(),
    enabled: integer('enabled', { mode: 'boolean' }).notNull().default(true),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [index('routines_user_idx').on(table.userId)],
)

export const activities = sqliteTable(
  'activities',
  {
    id: text('id').primaryKey(),
    routineId: text('routine_id')
      .notNull()
      .references(() => routines.id, { onDelete: 'cascade' }),
    // Order within the routine, as arranged in the editor.
    position: integer('position').notNull(),
    title: text('title').notNull(),
    // Wall-clock "HH:mm" in the user's time zone.
    time: text('time').notNull(),
    durationMinutes: integer('duration_minutes'),
    notes: text('notes'),
    // Null means no reminder.
    reminderMinutesBefore: integer('reminder_minutes_before'),
    // Next instant the reminder fires (Unix ms), or null when there is none.
    nextReminderAt: integer('next_reminder_at'),
  },
  (table) => [
    index('activities_routine_idx').on(table.routineId),
    index('activities_next_reminder_idx').on(table.nextReminderAt),
  ],
)

// Kept when an activity or routine is deleted, for history, so there is no
// foreign key to activities or routines.
export const completions = sqliteTable(
  'completions',
  {
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    routineId: text('routine_id').notNull(),
    activityId: text('activity_id').notNull(),
    // Local date "YYYY-MM-DD" in the user's time zone.
    date: text('date').notNull(),
    completedAt: text('completed_at').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.routineId, table.activityId, table.date] }),
  ],
)

export const pushSubscriptions = sqliteTable(
  'push_subscriptions',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    endpoint: text('endpoint').notNull(),
    p256dh: text('p256dh').notNull(),
    auth: text('auth').notNull(),
    createdAt: createdAt(),
    lastSuccessAt: text('last_success_at'),
  },
  (table) => [
    uniqueIndex('push_subscriptions_endpoint_unique').on(table.endpoint),
    index('push_subscriptions_user_idx').on(table.userId),
  ],
)
